// Confirmed from real grep of exceljs.js: 'read' operation requires
// params.source, either a file path string or a Buffer. Using the
// simpler file-path-string form — no separate file-in node needed.
msg.params = { source: '/share/wardstock_body_comp_import/test_sample.xlsx' };
return msg;

// Corrected after a real run: the field is 'sheet', not 'sheetName' as
// originally guessed. Node-RED's own error made this an easy, precise
// fix rather than another guess. Still assuming this wants the sheet's
// NAME as a string (confirmed 'Sheet1' via openpyxl earlier) rather
// than a numeric index — if that's also wrong, the next error should
// say so clearly (e.g. sheet-not-found vs a type mismatch).
msg.params = { range: 'A1:Q41', sheet: 'Sheet1' };
return msg;

try {
    msg.payload = JSON.stringify(msg.payload, null, 2);
} catch (e) {
    msg.payload = 'JSON.stringify failed: ' + e.message +
        ' | typeof payload: ' + typeof msg.payload +
        ' | top-level keys: ' + (msg.payload && typeof msg.payload === 'object' ? Object.keys(msg.payload).join(', ') : 'n/a');
}
return msg;
